companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}

# Build domain -> company name map
domain_map = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name } if c.domain != null and c.name != null else acc
}

# Process each contact
results = for contact in contacts {
    # Fix phone
    phone = contact.phone if contact.phone != null else ""
    phone_needs_fix = false
    new_phone = phone
    if phone != "" {
        # Check if already E.164: +1 followed by exactly 10 digits
        is_valid = regex.test(phone, "^\\+1[0-9]{10}$")
        if not is_valid {
            # Extract digits only
            digits = regex.replace(phone, "[^0-9]", "")
            # If 11 digits starting with 1, use last 10; if 10 digits, use them; else try what we have
            normalized = if text.length(digits) == 11 and text.starts_with(digits, "1") {
                return text.slice(digits, 1, 11)
            } else if text.length(digits) >= 10 {
                # take last 10
                return text.slice(digits, text.length(digits) - 10, text.length(digits))
            } else {
                return digits
            }
            if text.length(normalized) == 10 {
                new_phone = "+1" + normalized
                phone_needs_fix = true
            }
        }
    }

    # Fill company
    company_needs_fill = false
    new_company = contact.company
    company_empty = contact.company == null or contact.company == ""
    if company_empty and contact.email != null and contact.email != "" {
        parts = text.split(contact.email, "@")
        if list.length(parts) >= 2 {
            domain = parts[list.length(parts) - 1]
            domain_lower = text.lower(domain)
            if domain_lower in domain_map {
                new_company = domain_map[domain_lower]
                company_needs_fill = true
            } else if domain in domain_map {
                new_company = domain_map[domain]
                company_needs_fill = true
            }
        }
    }

    updated = false
    if phone_needs_fix and company_needs_fill {
        u = update_contact({ id: contact.id, phone: new_phone, company: new_company })
        updated = true
    } else if phone_needs_fix {
        u = update_contact({ id: contact.id, phone: new_phone })
        updated = true
    } else if company_needs_fill {
        u = update_contact({ id: contact.id, company: new_company })
        updated = true
    }

    return {
        phone_fixed: phone_needs_fix,
        company_filled: company_needs_fill
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

return { phones_fixed, companies_filled, total_contacts: list.length(contacts), companies: companies }

